// Year 8 history at grammar-school depth: Ancient Greece (a link to her Greek), medieval England,
// the Reformation, the Civil War, revolutions, industry, empire and the slave trade, the vote, the two
// World Wars and the Holocaust, with GCSE-style skills as the stretch. Serious subjects are told
// truthfully and respectfully. Grown-up text uses {she}/{her}/{him} tokens.

const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `history.${id}`, topic: `history.${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const mcq = (id, topic, prompt, options, explain, extra = {}) => ({
  id: `history.${id}`, topic: `history.${topic}`, kind: 'mcq', prompt,
  options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra,
});
const weighted = (id, topic, prompt, options, explain) => ({ id: `history.${id}`, topic: `history.${topic}`, kind: 'weighted', prompt, options: options.map(([text, weight, feedback]) => ({ text, weight, feedback })), explain });
const order = (id, topic, prompt, items, labels, explain) => ({ id: `history.${id}`, topic: `history.${topic}`, kind: 'order', prompt, items, labels, explain, axis: 'time' });
const C = { formats: ['choice'] };

const T = (id, title, prereqs, intro, teach, talk, extra = {}) => ({ id: `history.${id}`, title, kind: 'facts', prereqs: prereqs.map((p) => `history.${p}`), batch: 5, intro, teach, talk, ...extra });

const topics = [
  T('athens', 'Athens and the first democracy', [], 'In about 508 BC the Athenians began an experiment: government by the citizens themselves. It was the world’s first democracy, but “the people” meant far fewer people than you might think.', 'Explain how Athenian democracy was different from democracy in Britain today.', 'Ask {her} who could NOT vote in Athens, and whether that makes it a real democracy.'),
  T('sparta', 'Sparta: a city built for war', ['athens'], 'Sparta was Athens’ great rival: ruled by two kings, its boys trained for war from the age of seven, and its economy rested on the forced labour of the helots.', 'Explain why Sparta needed such a powerful army.', 'Ask {her} whether {she} would rather have grown up in Athens or Sparta, and why.'),
  T('persian-wars', 'The Persian Wars', ['athens', 'sparta'], 'Twice the vast Persian Empire invaded Greece, and twice the quarrelsome Greek cities beat it: at Marathon in 490 BC, and at Salamis and Plataea in 480–479 BC.', 'Explain why the Greeks won at Salamis even though the Persian fleet was larger.', 'Ask {her} what Herodotus is famous for, and why historians call him the “father of history”.'),
  T('alexander', 'Alexander the Great', ['persian-wars'], 'Alexander of Macedon became king at 20 and in thirteen years built an empire from Greece to India. His conquests spread Greek language and ideas across the known world.', 'Explain one reason why Alexander’s empire broke up so quickly after his death.', 'Ask {her} what Alexander had in common with the heroes of Greek myth.'),
  T('normans', 'Norman control and the medieval Church', [], 'After 1066 a few thousand Normans ruled about two million English people. Castles, the feudal system, the Domesday Book and the Church all helped them keep control.', 'Explain how the feudal system helped William keep control.', 'Ask {her} why the murder of Thomas Becket shocked medieval Europe.'),
  T('magna-carta', 'King John, Magna Carta and Parliament', ['normans'], 'In 1215 rebel barons forced King John to agree to Magna Carta, the first time a king of England accepted that he was under the law. Fifty years later, the first parliaments met.', 'Explain why Magna Carta still matters today.', 'Ask {her} what clause 39 of Magna Carta promised.'),
  T('black-death', 'The Black Death and the Peasants’ Revolt', ['normans'], 'In 1348 the plague reached England and killed perhaps a third to a half of the people. The survivors found their labour was suddenly precious, and in 1381 the peasants rose up.', 'Explain how the Black Death helped cause the Peasants’ Revolt.', 'Ask {her} what medieval people thought caused the plague, and what really did.'),
  T('reformation', 'The Tudors and the Reformation', ['magna-carta'], 'In sixteenth-century Europe the Church split into Catholic and Protestant. In England, Henry VIII broke with Rome, and his three children took the country in three different religious directions.', 'Explain why Henry VIII broke with the Catholic Church.', 'Ask {her} what the “middle way” of Elizabeth I was.'),
  T('civil-war', 'Stuarts, Civil War and the Glorious Revolution', ['reformation'], 'A king who believed God had chosen him clashed with a Parliament that controlled the money. The result was civil war, a king’s execution, eleven years without a monarch, and in 1688 a revolution that put Parliament in charge.', 'Explain the main causes of the English Civil War.', 'Ask {her} whether Oliver Cromwell was a hero or a villain.'),
  T('revolutions', 'The Enlightenment and the French Revolution', ['civil-war'], 'Enlightenment thinkers argued that reason, not tradition, should decide how people are governed. In 1789 France put the idea into practice, with dramatic and violent results.', 'Explain how Enlightenment ideas helped cause the French Revolution.', 'Ask {her} what “Liberty, Equality, Fraternity” means.'),
  T('industrial', 'The Industrial Revolution', ['civil-war'], 'From about 1750, Britain became the first country to industrialise: steam power, factories, canals and railways transformed how people lived and worked, for better and for worse.', 'Explain why Britain industrialised first.', 'Ask {her} what life was like for a child working in a cotton mill around 1800.'),
  T('empire', 'Empire, the slave trade and abolition', ['industrial'], 'Britain built the largest empire in history. For more than two centuries part of its wealth came from the transatlantic trade in enslaved Africans, until enslaved people’s resistance and a long campaign brought it to an end.', 'Explain the different groups who helped bring about abolition, including enslaved people themselves.', 'Ask {her} why the British government paid compensation to slave owners but not to the people who had been enslaved.'),
  T('vote', 'Reform and the fight for the vote', ['industrial'], 'In 1830 only about one adult in ten could vote. A century of campaigning, from the Chartists to the suffragists and suffragettes, changed that.', 'Explain the difference between the suffragists and the suffragettes.', 'Ask {her} which was more effective: peaceful persuasion or direct action?'),
  T('ww1', 'The First World War', ['empire'], 'The war that began in 1914 was fought on an industrial scale. Millions served in the trenches, women took on new work at home, and the world that came out of it in 1918 was very different.', 'Explain the long-term causes of the First World War (militarism, alliances, imperialism, nationalism).', 'On Remembrance Sunday, talk with {her} about why we still remember the war.'),
  T('ww2', 'The Second World War and the Holocaust', ['ww1'], 'From 1939 to 1945 the world was at war again. In the shadow of the war, Nazi Germany murdered six million Jews and persecuted many others: the Holocaust. We study it to remember the victims and to understand how it could happen.', 'Explain how Nazi persecution of Jewish people grew step by step from 1933.', 'Ask {her} why Holocaust Memorial Day is held on 27 January.'),
  T('skills', 'Thinking like a historian', [], 'Historians don’t just know facts. They explain causes and consequences, judge change and significance, and question their sources: who made this, when, and why?', 'Explain what “provenance” means and why it matters.', 'Show {her} a newspaper headline and ask what its purpose is, and whether that makes it unreliable.'),
  // stretch: GCSE-style depth
  T('sources', 'Sources and interpretations, GCSE style', ['skills'], 'At GCSE you will judge how useful a source is from its content AND its provenance, and explain why historians’ interpretations differ. Here is a head start.', 'Explain how a biased source can still be useful.', 'Ask {her} why two historians might disagree about the same event.', { tier: 'stretch' }),
  T('cold-war', 'The Cold War', ['ww2'], 'After 1945 the USA and the USSR, allies against Hitler, became rivals. For forty-five years they competed in arms, space and ideas, and came close to nuclear war, without fighting each other directly.', 'Explain why the Cuban Missile Crisis was the most dangerous moment of the Cold War.', 'Ask {her} why it was called a “cold” war.', { tier: 'stretch' }),
  T('golden-age', 'Baghdad and the Islamic Golden Age', ['athens'], 'While much of Europe was in the early Middle Ages, Baghdad was one of the greatest cities in the world, where scholars translated Greek books and made new discoveries in maths, medicine and science.', 'Explain how Greek learning reached medieval Europe through the Islamic world.', 'Ask {her} which English words come from Arabic (algebra, algorithm, alchemy…).', { tier: 'stretch' }),
];

const items = [
  // --- Athens
  fact('ath.year', 'athens', 'In about which year did Cleisthenes’ reforms create democracy in Athens?', '508 BC', ['776 BC', '323 BC', 'AD 43'], 'Cleisthenes reorganised the citizens in about 508–507 BC, giving power to the assembly.', { accept: ['508', '508bc', '507 bc', '507bc', '507'] }),
  fact('ath.word', 'athens', 'The word “democracy” comes from two Greek words. What do they mean?', 'people + power (rule)', ['many + votes', 'city + law', 'free + speech'], 'dēmos = the people, kratos = power or rule.', C),
  mcq('ath.who', 'athens', 'Who could vote in the Athenian assembly?', [['Adult male citizens only', true], ['Every adult living in Athens', false, 'Women, slaves and foreign residents (metics) were all excluded.'], ['Only rich landowners', false, 'Poor citizens could vote too: that was the radical part.']], 'Perhaps only 10–20% of the people of Athens were adult male citizens.'),
  mcq('ath.direct', 'athens', 'How was Athenian democracy different from British democracy today?', [['Citizens voted on laws themselves (direct democracy) rather than electing representatives', true], ['Athens had a prime minister', false, 'There was no prime minister; the assembly of citizens decided.'], ['Athenians voted online', false, 'They met in person on the Pnyx hill.']], 'Britain is a representative democracy: we elect MPs to decide for us. Athens was direct.'),
  fact('ath.ostracism', 'athens', 'Each year Athenians could vote to exile a too-powerful citizen for ten years by scratching his name on a piece of pottery. What was this called?', 'ostracism', ['impeachment', 'banishment by lot', 'the Olympics'], 'The pottery shards were called ostraka, which gives us the English word “ostracise”.', { accept: ['ostracism', 'ostracise', 'ostracize'] }),
  mcq('ath.lot', 'athens', 'How were most Athenian officials and jurors chosen?', [['By lot (random selection)', true], ['By election only', false, 'Generals were elected, but most posts were filled by lot, which Athenians thought fairer.'], ['By the king', false, 'Athens had no king by then.']], 'Choosing by lot stopped the rich and famous from taking every job.'),
  fact('ath.pericles', 'athens', 'Which Athenian leader of the 440s–430s BC is linked with the building of the Parthenon?', 'Pericles', ['Leonidas', 'Alexander', 'Xerxes'], 'Pericles led Athens at the height of its power; the Parthenon was built 447–432 BC.', { accept: ['perikles'] }),
  fact('ath.parthenon', 'athens', 'The Parthenon on the Acropolis was a temple to which goddess?', 'Athena', ['Hera', 'Aphrodite', 'Artemis'], 'Athena was the patron goddess of Athens, the city named after her.', { accept: ['athene', 'athena parthenos'] }),
  mcq('ath.agora', 'athens', 'What was the agora?', [['The open market and meeting place at the heart of the city', true], ['A type of warship', false, 'That was a trireme.'], ['The Spartan training system', false, 'That was the agoge.']], 'The agora was where Athenians shopped, gossiped and argued about politics.'),
  weighted('ath.judge', 'athens', 'Was Athens a true democracy? Which answer would a top historian give?', [['It was revolutionary for its time, because poor citizens had real power, but it excluded most of the population, so it was a limited democracy', 1, 'A balanced judgement that weighs both sides.'], ['Yes, because everyone could vote', 0, 'Not everyone: women, slaves and metics could not.'], ['No, because women could not vote', 0.5, 'True, but this ignores how radical it was to give power to poor men.']], 'Good historical judgements weigh evidence on both sides and reach a balanced conclusion.'),
  // --- Sparta
  fact('sp.agoge', 'sparta', 'What was the name of the tough military training Spartan boys began at about seven?', 'the agoge', ['the agora', 'the phalanx', 'the trireme'], 'Boys lived in barracks, were kept hungry and learned to endure pain.', { ...C }),
  fact('sp.helots', 'sparta', 'Who were the helots?', 'an enslaved people who farmed Sparta’s land', ['Sparta’s kings', 'foreign traders in Athens', 'Persian soldiers'], 'The helots outnumbered Spartan citizens many times over, which is one reason Sparta needed a powerful army.', C),
  mcq('sp.kings', 'sparta', 'How was Sparta governed?', [['By two kings, a council of elders and five elected ephors', true], ['By a direct democracy like Athens', false, 'Sparta was an oligarchy: rule by the few.'], ['By a single emperor', false, 'Sparta unusually had TWO kings at once.']], 'Sparta mixed kingship, an elite council and elected officials: rule by the few.'),
  mcq('sp.women', 'sparta', 'How were Spartan women different from Athenian women?', [['They could own land and had more freedom, and girls did athletics', true], ['They could vote in the assembly', false, 'Neither city let women vote.'], ['They fought in the army', false, 'Spartan women did not fight, but they did train their bodies.']], 'Sparta valued strong mothers for strong soldiers, so girls exercised and women ran estates.'),
  mcq('sp.why', 'sparta', 'Why did Sparta need such a powerful army?', [['To keep the much larger helot population under control, as well as to fight enemies', true], ['Because the Spartans had no farms', false, 'They had farms, worked by the helots.'], ['Because Athens forced them to', false, 'Sparta chose its own path.']], 'Fear of a helot revolt shaped the whole of Spartan society.'),
  fact('sp.war', 'sparta', 'Which long war between Athens and Sparta (431–404 BC) ended in Sparta’s victory?', 'the Peloponnesian War', ['the Persian War', 'the Trojan War', 'the Hundred Years War'], 'The historian Thucydides wrote its history; Athens finally surrendered in 404 BC.', C),
  mcq('sp.phalanx', 'sparta', 'What was a phalanx?', [['A tight block of armoured soldiers with overlapping shields and long spears', true], ['A Spartan festival', false, 'It was a battle formation.'], ['A type of temple', false, 'It was a battle formation.']], 'Each soldier’s shield partly protected the man to his left, so the line depended on everyone holding firm.'),
  // --- Persian Wars
  fact('pw.marathon', 'persian-wars', 'In which year did the Athenians defeat the Persians at the Battle of Marathon?', '490 BC', ['480 BC', '508 BC', '323 BC'], 'Darius I’s invasion was beaten by an Athenian army, with help from Plataea.', { accept: ['490', '490bc'] }),
  fact('pw.darius', 'persian-wars', 'Which Persian king sent the army defeated at Marathon?', 'Darius I', ['Xerxes', 'Cyrus the Great', 'Alexander'], 'Darius’s son Xerxes led the second, much larger invasion in 480 BC.', { accept: ['darius', 'darius the great', 'darius 1'] }),
  fact('pw.leonidas', 'persian-wars', 'Which Spartan king led the stand at the pass of Thermopylae in 480 BC?', 'Leonidas', ['Pericles', 'Themistocles', 'Miltiades'], 'Leonidas and his 300 Spartans, with several thousand other Greeks at first, held the pass for three days.', { accept: ['king leonidas'] }),
  mcq('pw.thermo', 'persian-wars', 'How did the Persians finally get past the Greeks at Thermopylae?', [['A local man, Ephialtes, showed them a mountain path round the back', true], ['They had far more ships', false, 'Thermopylae was a land battle in a narrow pass.'], ['The Spartans ran out of food', false, 'They were outflanked by a hidden path.']], 'The pass was narrow enough for a few to hold, until they were surrounded.'),
  fact('pw.salamis', 'persian-wars', 'Which sea battle in 480 BC, planned by Themistocles, destroyed much of the Persian fleet?', 'Salamis', ['Marathon', 'Plataea', 'Actium'], 'The Greeks lured the Persian ships into narrow straits where their numbers did not help.', { accept: ['battle of salamis'] }),
  mcq('pw.why', 'persian-wars', 'Why did the Greeks win at Salamis even though the Persians had more ships?', [['In the narrow straits the Persian ships got in each other’s way, while Greek triremes rammed them', true], ['The Persians had no sailors', false, 'They had excellent Phoenician sailors.'], ['A storm sank them all first', false, 'Storms had hurt the Persians earlier, but Salamis was won by tactics.']], 'Themistocles chose the battlefield so that numbers did not matter.'),
  fact('pw.trireme', 'persian-wars', 'What was a Greek warship with three rows of oars, and a bronze ram on the front, called?', 'a trireme', ['a longship', 'a galleon', 'a phalanx'], 'About 170 rowers powered each trireme.', { accept: ['trireme'] }),
  fact('pw.herodotus', 'persian-wars', 'Which writer, called “the father of history”, wrote an account of the Persian Wars?', 'Herodotus', ['Homer', 'Thucydides', 'Plato'], 'Herodotus travelled widely and asked questions: his word “historiai” means “enquiries”.', { accept: ['herodotos'] }),
  order('pw.order', 'persian-wars', 'Put these in order, earliest first.', ['Democracy begins in Athens', 'Battle of Marathon', 'Battles of Thermopylae and Salamis', 'Battle of Plataea'], ['c. 508 BC', '490 BC', '480 BC', '479 BC'], 'In BC dates, bigger numbers are earlier. Plataea in 479 BC ended the invasion.'),
  mcq('pw.marathon-run', 'persian-wars', 'What does the story of Pheidippides tell historians about Marathon?', [['It is a later legend, so it shows how the battle was remembered rather than what definitely happened', true], ['It proves the first marathon race was run in 490 BC', false, 'The 26-mile run to Athens appears only in much later writers.'], ['Nothing, because legends are useless', false, 'Legends are useful evidence of how people remembered events.']], 'Herodotus says Pheidippides ran to Sparta for help; the run back to Athens with news of victory comes from writers centuries later.'),
  // --- Alexander
  fact('al.born', 'alexander', 'Which kingdom, north of Greece, was Alexander the Great from?', 'Macedon', ['Sparta', 'Persia', 'Egypt'], 'Alexander was born in 356 BC, son of Philip II of Macedon.', { accept: ['macedonia'] }),
  fact('al.tutor', 'alexander', 'Which famous philosopher was Alexander’s teacher?', 'Aristotle', ['Socrates', 'Plato', 'Herodotus'], 'Aristotle taught the young prince for about three years.', {}),
  fact('al.city', 'alexander', 'Which great city in Egypt did Alexander found in 331 BC?', 'Alexandria', ['Cairo', 'Memphis', 'Athens'], 'Alexandria became famous for its lighthouse and its great library.', {}),
  fact('al.horse', 'alexander', 'What was the name of Alexander’s famous horse?', 'Bucephalus', ['Pegasus', 'Incitatus', 'Arion'], 'Legend says only the young Alexander could tame him, because he noticed the horse was afraid of its own shadow.', { accept: ['boukephalas'] }),
  fact('al.died', 'alexander', 'How old was Alexander when he died in Babylon in 323 BC?', '32', ['20', '45', '60'], 'In just thirteen years as king he had conquered an empire stretching to India.', { accept: ['32 years old', 'thirty-two'] }),
  mcq('al.persia', 'alexander', 'Which empire did Alexander conquer, defeating King Darius III?', [['The Persian Empire', true], ['The Roman Empire', false, 'Rome was not yet a great power.'], ['The Chinese Empire', false, 'Alexander never reached China.']], 'Victories at Issus (333 BC) and Gaugamela (331 BC) brought down Persia.'),
  mcq('al.legacy', 'alexander', 'What was Alexander’s most lasting legacy?', [['Greek language and culture spread across the eastern Mediterranean and beyond (the Hellenistic world)', true], ['A united empire that lasted 500 years', false, 'His empire split between his generals soon after he died.'], ['He invented democracy', false, 'Democracy was Athenian, 170 years earlier.']], 'For centuries afterwards, Greek was the shared language of the eastern Mediterranean: even the New Testament was written in it.'),
  mcq('al.split', 'alexander', 'Why did Alexander’s empire break up so quickly?', [['He died young without an adult heir, and his generals fought over the lands', true], ['The Romans conquered it the next year', false, 'Rome took over parts only much later.'], ['He gave it away', false, 'His generals (the Successors) divided it by war.']], 'Empires built around one brilliant individual often struggle when that person dies.'),
  // --- Normans and the Church
  mcq('no.feudal', 'normans', 'How did the feudal system help William control England?', [['He gave land to barons in return for loyalty and knights, and they did the same down the chain', true], ['Everyone voted for William', false, 'He won the crown by conquest.'], ['Peasants owned their own land', false, 'Most peasants were villeins, tied to their lord’s land.']], 'Land was exchanged for loyalty and service: king, barons, knights, peasants.'),
  fact('no.domesday', 'normans', 'Which great survey of land and property did William order, completed in 1086?', 'the Domesday Book', ['Magna Carta', 'the Bayeux Tapestry', 'the Doomsday Charter'], 'It recorded who held what, so William knew how much tax he could raise.', { accept: ['domesday book', 'domesday'] }),
  mcq('no.harrying', 'normans', 'What was the Harrying of the North (1069–70)?', [['William’s destruction of villages, crops and animals in northern England to crush rebellion', true], ['A Viking invasion', false, 'It was William’s own campaign.'], ['A peaceful survey of the north', false, 'It was brutal: many people starved.']], 'Chroniclers recorded famine and death across Yorkshire. It was harsh, and effective.'),
  mcq('no.castles', 'normans', 'Why did the Normans build motte and bailey castles so quickly after 1066?', [['They could be built fast from earth and wood to control the local area', true], ['They were made of stone, which was quick to cut', false, 'Stone keeps came later; the first castles were timber.'], ['They were palaces for the English', false, 'They were bases to dominate the English.']], 'Around 500 castles were built in William’s reign.'),
  fact('no.tithe', 'normans', 'What was the tithe that peasants paid to the Church?', 'one tenth of what they produced', ['one half of their land', 'a penny a year', 'nothing at all'], 'The Church was enormously rich and powerful in medieval England.', C),
  fact('no.becket', 'normans', 'Which Archbishop of Canterbury was murdered in his cathedral in 1170 after quarrelling with Henry II?', 'Thomas Becket', ['Thomas Cranmer', 'Thomas More', 'Thomas Cromwell'], 'Four knights killed him after hearing the king’s angry words. Becket became a saint, and Canterbury a great pilgrimage site.', { accept: ['becket', 'thomas a becket', 'saint thomas becket'] }),
  mcq('no.becket-why', 'normans', 'Why did Henry II and Becket quarrel?', [['Over whether churchmen accused of crimes should be tried in the king’s courts or the Church’s courts', true], ['Over who would marry the king’s daughter', false, 'It was about power: Church versus Crown.'], ['Over the Crusades', false, 'The quarrel was about law and power in England.']], 'The dispute was about who had more power in England: the king or the Church.'),
  mcq('no.doom', 'normans', 'What was the purpose of a medieval “doom painting” on a church wall?', [['To show ordinary people, most of whom could not read, what heaven and hell were like', true], ['To decorate a castle', false, 'Doom paintings were in churches.'], ['To record the Domesday survey', false, 'Different “doom”: it means judgement.']], 'Pictures taught a mostly illiterate population about the Last Judgement.'),
  // --- Magna Carta
  fact('mc.year', 'magna-carta', 'In which year did King John agree to Magna Carta?', '1215', ['1066', '1265', '1381'], 'At Runnymede, by the River Thames, in June 1215.', {}),
  fact('mc.place', 'magna-carta', 'In which meadow beside the Thames was Magna Carta agreed?', 'Runnymede', ['Hastings', 'Smithfield', 'Bosworth'], 'Runnymede is near Windsor.', {}),
  mcq('mc.why', 'magna-carta', 'Why were the barons so angry with King John?', [['He had lost his lands in France, raised heavy taxes and quarrelled with the Pope', true], ['He refused to go on crusade', false, 'That was not the main grievance.'], ['He gave the vote to peasants', false, 'Nobody had a vote then.']], 'Losing Normandy in 1204, then taxing heavily to win it back, turned the barons against him.'),
  mcq('mc.39', 'magna-carta', 'What did clause 39 of Magna Carta promise?', [['No free man would be imprisoned or punished except by the lawful judgement of his peers or the law of the land', true], ['Every man could vote', false, 'Voting came centuries later.'], ['Taxes would be abolished', false, 'Taxes needed consent, not abolition.']], 'This idea, that the king is under the law, still underpins British and American law.'),
  mcq('mc.matter', 'magna-carta', 'Why is Magna Carta still seen as significant?', [['It established the principle that even the king must obey the law', true], ['It gave everyone equal rights in 1215', false, 'It mostly protected barons and free men, not villeins.'], ['It ended the monarchy', false, 'England kept its kings.']], 'Its importance grew over time as later generations reinterpreted it.'),
  fact('mc.montfort', 'magna-carta', 'In 1265 which rebel baron called a parliament that included representatives of the towns for the first time?', 'Simon de Montfort', ['Thomas Becket', 'William Marshal', 'Wat Tyler'], 'De Montfort’s parliament is often seen as a step towards the House of Commons.', { accept: ['de montfort', 'montfort'] }),
  // --- Black Death and Peasants' Revolt
  fact('bd.year', 'black-death', 'In which year did the Black Death reach England?', '1348', ['1066', '1381', '1666'], 'It arrived at Melcombe (now Weymouth) in Dorset in the summer of 1348.', {}),
  mcq('bd.toll', 'black-death', 'About what proportion of England’s people died in the Black Death?', [['Perhaps a third to a half', true], ['About one in a hundred', false, 'It was far worse than that.'], ['Everyone except the king', false, 'Many survived, but losses were enormous.']], 'Historians’ estimates vary, but somewhere between 30% and 50% is usual.'),
  mcq('bd.cause', 'black-death', 'What do we now know caused the Black Death?', [['Bacteria (Yersinia pestis) spread by fleas on rats, and between people', true], ['Bad air from rotting rubbish', false, 'That was the medieval “miasma” theory.'], ['The position of the planets', false, 'Some medieval doctors believed this, but it is wrong.']], 'Medieval people blamed God’s punishment, bad air or the stars. Germ theory came 500 years later.'),
  mcq('bd.believed', 'black-death', 'Why did some people called flagellants whip themselves in public?', [['They believed the plague was God’s punishment and hoped to win forgiveness', true], ['To spread the disease', false, 'They thought they were stopping it.'], ['As a punishment for stealing', false, 'It was voluntary religious penance.']], 'Religion shaped how medieval people understood disaster.'),
  mcq('bd.effect', 'black-death', 'How did the Black Death change life for surviving peasants?', [['Labour was scarce, so peasants could demand higher wages and better conditions', true], ['They all became knights', false, 'They stayed peasants, but with more bargaining power.'], ['Nothing changed', false, 'Labour shortages shook the feudal system.']], 'The government tried to freeze wages with the Statute of Labourers (1351), which caused resentment.'),
  fact('pr.year', 'black-death', 'In which year did the Peasants’ Revolt take place?', '1381', ['1348', '1215', '1485'], 'Rebels from Essex and Kent marched on London in June 1381.', {}),
  mcq('pr.trigger', 'black-death', 'What was the short-term trigger of the Peasants’ Revolt?', [['A third poll tax, charged on everyone over 15', true], ['The murder of Thomas Becket', false, 'That was in 1170.'], ['The Battle of Hastings', false, 'That was in 1066.']], 'Long-term causes included anger over wages and serfdom; the poll tax was the spark.'),
  fact('pr.tyler', 'black-death', 'Which leader of the Peasants’ Revolt was killed while meeting the king at Smithfield?', 'Wat Tyler', ['John Ball', 'Jack Cade', 'Robert Kett'], 'He was struck down by the Lord Mayor of London, William Walworth.', { accept: ['tyler'] }),
  fact('pr.king', 'black-death', 'How old was King Richard II when he faced the rebels in 1381?', '14', ['8', '21', '40'], 'The boy king promised the rebels freedom, then broke his promises once they went home.', { accept: ['fourteen', '14 years old'] }),
  mcq('pr.ball', 'black-death', '“When Adam delved and Eve span, who was then the gentleman?” What was the preacher John Ball arguing?', [['That God made all people equal, so there should be no lords and serfs', true], ['That farming was better than spinning', false, 'It is a question about equality.'], ['That the king should marry', false, 'It is about equality.']], 'At the start of the world, Adam dug and Eve spun: nobody was a lord. So why should anyone be a serf?'),
  // --- Reformation
  fact('rf.luther', 'reformation', 'Which German monk began the Reformation in 1517 by criticising the Church?', 'Martin Luther', ['John Calvin', 'Thomas Cranmer', 'Erasmus'], 'His 95 Theses attacked the sale of indulgences (pardons for sin).', { accept: ['luther'] }),
  mcq('rf.why', 'reformation', 'Why did Henry VIII break with the Catholic Church?', [['The Pope refused to annul his marriage to Catherine of Aragon, and Henry wanted a male heir and control of the Church', true], ['Henry had become a Protestant like Luther', false, 'Henry had attacked Luther and stayed Catholic in many beliefs.'], ['The Pope invaded England', false, 'There was no invasion.']], 'The break was about Henry’s marriage, his need for a son, power and money, more than belief.'),
  fact('rf.supremacy', 'reformation', 'Which 1534 Act made Henry VIII Supreme Head of the Church of England?', 'the Act of Supremacy', ['the Bill of Rights', 'the Act of Union', 'Magna Carta'], 'Refusing to accept Henry’s new position was treason: Sir Thomas More was executed in 1535.', { ...C }),
  mcq('rf.monasteries', 'reformation', 'Why did Henry VIII close the monasteries between 1536 and 1541?', [['To take their wealth and land, and remove loyalty to the Pope', true], ['Because the monks asked to leave', false, 'Most did not.'], ['To build schools', false, 'A few schools were founded, but money and power were the main motives.']], 'Thomas Cromwell organised the Dissolution. The Pilgrimage of Grace (1536) rose partly in protest.'),
  order('rf.rulers', 'reformation', 'Put these Tudor monarchs in order of their reigns.', ['Henry VIII', 'Edward VI', 'Mary I', 'Elizabeth I'], ['1509', '1547', '1553', '1558'], 'Henry’s three children ruled in turn: Edward, Mary, then Elizabeth.'),
  mcq('rf.mary', 'reformation', 'What did Mary I try to do?', [['Return England to the Catholic Church', true], ['Make England strictly Protestant', false, 'That was her brother Edward VI.'], ['Abolish religion', false, 'No Tudor tried that.']], 'Around 280 Protestants were burned for heresy in her reign, earning her the name “Bloody Mary” from Protestant writers.'),
  mcq('rf.elizabeth', 'reformation', 'What was Elizabeth I’s “middle way” (the religious settlement of 1559)?', [['A Protestant Church of England that kept some Catholic-style traditions to keep most people content', true], ['Allowing complete freedom of religion', false, 'Everyone still had to attend the Church of England.'], ['Becoming Catholic again', false, 'It was Protestant, but moderate.']], 'She wanted outward loyalty and peace rather than perfect agreement in belief.'),
  fact('rf.bible', 'reformation', 'What important change happened in English churches in 1539?', 'an official Bible in English was placed in every parish church', ['the churches were all closed', 'services were held in French', 'the Pope visited England'], 'The Great Bible meant ordinary people could hear and read the Bible in their own language.', C),
  // --- Civil War
  fact('cw.gunpowder', 'civil-war', 'In which year did Catholic plotters try to blow up King James I and Parliament?', '1605', ['1642', '1588', '1666'], 'Guy Fawkes was caught guarding the gunpowder on 5 November 1605.', {}),
  mcq('cw.divine', 'civil-war', 'What did Charles I believe about his power?', [['The Divine Right of Kings: God had chosen him, so he answered only to God', true], ['That Parliament should rule', false, 'That was what his opponents wanted.'], ['That the people should elect the king', false, 'Not in the 1600s!']], 'Charles ruled without Parliament for eleven years (1629–40).'),
  mcq('cw.causes', 'civil-war', 'Which was NOT a cause of the English Civil War?', [['A French invasion of England', true], ['Arguments over money and taxes such as Ship Money', false, 'This WAS a cause.'], ['Fears that Charles was making the Church too Catholic', false, 'This WAS a cause.'], ['Charles’s belief in the Divine Right of Kings', false, 'This WAS a cause.']], 'Money, religion and power together caused the war.'),
  fact('cw.start', 'civil-war', 'In which year did the English Civil War begin?', '1642', ['1605', '1649', '1660'], 'Charles raised his standard at Nottingham in August 1642.', {}),
  mcq('cw.sides', 'civil-war', 'Who were the “Roundheads” and the “Cavaliers”?', [['Supporters of Parliament and supporters of the king', true], ['English and Scottish armies', false, 'Both sides were mostly English.'], ['Catholics and Protestants', false, 'Both sides were largely Protestant.']], 'The nicknames came from short haircuts (Roundheads) and fashionable riders (Cavaliers).'),
  fact('cw.naseby', 'civil-war', 'At which battle in 1645 did the New Model Army decisively defeat the king?', 'Naseby', ['Edgehill', 'Marston Moor', 'Bosworth'], 'After Naseby, the royalist cause collapsed.', { accept: ['battle of naseby'] }),
  fact('cw.execution', 'civil-war', 'In which year was Charles I executed?', '1649', ['1642', '1660', '1688'], 'He was beheaded outside the Banqueting House in Whitehall on 30 January 1649.', {}),
  fact('cw.cromwell', 'civil-war', 'Who ruled as Lord Protector from 1653 until his death in 1658?', 'Oliver Cromwell', ['Thomas Cromwell', 'Charles II', 'Thomas Fairfax'], 'Not to be confused with Thomas Cromwell, Henry VIII’s minister a century earlier.', { accept: ['cromwell'] }),
  mcq('cw.cromwell-view', 'civil-war', 'Why do historians disagree about Oliver Cromwell?', [['He defended Parliament and religious freedom for some Protestants, but ruled by army power and acted brutally in Ireland', true], ['Nobody knows what he did', false, 'His life is very well recorded.'], ['He was a king', false, 'He refused the crown in 1657.']], 'Interpretations differ because his actions really were mixed: a good chance to weigh evidence.'),
  fact('cw.restoration', 'civil-war', 'In 1660 the monarchy returned. Who became king?', 'Charles II', ['James II', 'William III', 'Charles I'], 'This is called the Restoration.', { accept: ['charles the second', 'king charles ii'] }),
  mcq('cw.glorious', 'civil-war', 'What happened in the “Glorious Revolution” of 1688?', [['James II was replaced by William III and Mary II, who accepted limits on royal power', true], ['Charles I was executed', false, 'That was 1649.'], ['Parliament was abolished', false, 'Parliament became stronger.']], 'The Bill of Rights (1689) meant monarchs could not tax or keep an army in peacetime without Parliament’s consent.'),
  // --- Enlightenment and French Revolution
  mcq('fr.enlight', 'revolutions', 'What was the central idea of the Enlightenment?', [['That reason and evidence, not tradition or authority, should guide how we understand the world and govern it', true], ['That kings were chosen by God', false, 'Enlightenment thinkers challenged this.'], ['That science was dangerous', false, 'They championed science.']], 'Thinkers such as Locke, Montesquieu and Voltaire questioned old authorities.'),
  fact('fr.locke', 'revolutions', 'Which English philosopher argued that people have natural rights to life, liberty and property?', 'John Locke', ['Isaac Newton', 'Thomas Hobbes', 'Oliver Cromwell'], 'Locke’s ideas influenced both the American and French revolutions.', { accept: ['locke'] }),
  fact('fr.bastille', 'revolutions', 'On which date was the Bastille prison in Paris stormed, now France’s national day?', '14 July 1789', ['4 July 1776', '11 November 1918', '5 November 1605'], 'The storming of the Bastille became the symbol of the Revolution.', C),
  fact('fr.motto', 'revolutions', 'What was the motto of the French Revolution?', 'Liberty, Equality, Fraternity', ['Peace, Land, Bread', 'Deeds not words', 'God save the King'], 'Liberté, égalité, fraternité is still France’s motto.', C),
  mcq('fr.causes', 'revolutions', 'Which was a cause of the French Revolution?', [['The government was nearly bankrupt, bread was expensive, and the Third Estate paid most taxes but had little power', true], ['France had just won a war against Britain and was very rich', false, 'Helping America win independence had left France deep in debt.'], ['The king had given everyone the vote', false, 'Ordinary people had almost no power.']], 'Debt, hunger, unfairness and new ideas together created a revolution.'),
  fact('fr.louis', 'revolutions', 'Which French king was executed by guillotine in January 1793?', 'Louis XVI', ['Louis XIV', 'Napoleon', 'Charles X'], 'His queen, Marie Antoinette, was executed in October 1793.', { accept: ['louis 16', 'louis the sixteenth'] }),
  mcq('fr.terror', 'revolutions', 'What was the Reign of Terror (1793–94)?', [['A period when the revolutionary government executed thousands of suspected enemies', true], ['Napoleon’s invasion of Russia', false, 'That was 1812.'], ['A British blockade of France', false, 'It was violence inside France.']], 'Led by Robespierre, who was himself guillotined in July 1794.'),
  fact('fr.waterloo', 'revolutions', 'At which battle in 1815 was Napoleon finally defeated?', 'Waterloo', ['Trafalgar', 'Austerlitz', 'Hastings'], 'The Duke of Wellington and the Prussian commander Blücher defeated him in what is now Belgium.', { accept: ['battle of waterloo'] }),
  // --- Industrial Revolution
  mcq('ir.why', 'industrial', 'Which reason helps explain why Britain industrialised first?', [['Plentiful coal and iron, money from trade and empire, inventors, and a growing population', true], ['Britain had the warmest weather', false, 'Climate was not the reason.'], ['Britain had no farms', false, 'An agricultural revolution actually helped feed the workers.']], 'Historians stress a mix of factors: resources, capital, markets, ideas and stability.'),
  fact('ir.watt', 'industrial', 'Which Scottish engineer greatly improved the steam engine in the 1760s and 1770s?', 'James Watt', ['George Stephenson', 'Richard Arkwright', 'Isambard Kingdom Brunel'], 'His separate condenser made engines far more efficient. The unit of power, the watt, is named after him.', { accept: ['watt'] }),
  fact('ir.arkwright', 'industrial', 'Whose water-powered mill at Cromford (1771) is often called the first modern factory?', 'Richard Arkwright', ['James Watt', 'Abraham Darby', 'Josiah Wedgwood'], 'Arkwright’s water frame spun cotton thread by machine.', { accept: ['arkwright'] }),
  fact('ir.railway', 'industrial', 'Which railway, opened in 1830, was the first to carry passengers between two cities using only steam locomotives?', 'the Liverpool and Manchester Railway', ['the Stockton and Darlington Railway', 'the Great Western Railway', 'the London Underground'], 'Stephenson’s Rocket had won the Rainhill Trials to work on it in 1829.', C),
  mcq('ir.children', 'industrial', 'What did the Factory Act of 1833 do?', [['Banned children under 9 from working in textile factories and limited hours for older children', true], ['Banned all child labour', false, 'It was a first step, not a complete ban.'], ['Gave factory workers the vote', false, 'That came much later.']], 'Inspectors were appointed to enforce it, though there were few of them.'),
  mcq('ir.cholera', 'industrial', 'In 1854 Dr John Snow traced a cholera outbreak in London to what?', [['A water pump on Broad Street', true], ['Bad air from the Thames', false, 'Most people thought so, but Snow showed it was contaminated water.'], ['Rats in the sewers', false, 'His evidence pointed to the water pump.']], 'Snow mapped the deaths and found them clustered round the pump: an early triumph of evidence.'),
  mcq('ir.luddites', 'industrial', 'Who were the Luddites (1811–16)?', [['Workers who smashed new machines they feared would take their jobs', true], ['Factory owners who built canals', false, 'They were skilled workers protesting.'], ['A railway company', false, 'They were protesters.']], 'Today a “Luddite” means someone who resists new technology.'),
  weighted('ir.judge', 'industrial', 'Was the Industrial Revolution good for ordinary people? Which is the strongest answer?', [['In the short term many suffered from dangerous work and crowded, unhealthy towns, but in the long run living standards rose greatly', 1, 'A balanced judgement that considers time scale.'], ['Yes, everyone got rich', 0, 'Many workers lived in terrible conditions.'], ['No, it only made things worse', 0.5, 'For many at first, yes; but long-term wages, health and life expectancy improved.']], 'Strong answers consider different groups and different time scales.'),
  // --- Empire, the slave trade and abolition
  mcq('em.triangle', 'empire', 'What was the “triangular trade”?', [['Ships took goods from Britain to West Africa, enslaved Africans across the Atlantic, and sugar, cotton and tobacco back to Britain', true], ['Trade between Britain, France and Spain', false, 'It linked Europe, Africa and the Americas.'], ['A trade in triangles', false, 'It is named after the shape of the route.']], 'Each leg made profits for British merchants, built on the suffering of enslaved people.'),
  fact('em.middle', 'empire', 'What was the voyage of enslaved Africans across the Atlantic called?', 'the Middle Passage', ['the Northwest Passage', 'the Long March', 'the Grand Tour'], 'Enslaved people were packed in terrible conditions; many died on the voyage.', C),
  mcq('em.scale', 'empire', 'About how many Africans were forced onto ships across the Atlantic in the whole transatlantic slave trade?', [['About 12 million', true], ['About 12 thousand', false, 'The scale was a thousand times greater.'], ['About 1 billion', false, 'That is far too many: about 12.5 million is the usual estimate.']], 'British ships carried around 3 million of them. Behind each number is a person.'),
  fact('em.equiano', 'empire', 'Which formerly enslaved man published a best-selling autobiography in 1789 that helped the abolition campaign?', 'Olaudah Equiano', ['Toussaint Louverture', 'Samuel Sharpe', 'William Wilberforce'], 'Equiano bought his freedom, settled in Britain and campaigned against slavery.', { accept: ['equiano', 'gustavus vassa'] }),
  fact('em.wilberforce', 'empire', 'Which MP led the campaign against the slave trade in Parliament?', 'William Wilberforce', ['Thomas Clarkson', 'William Pitt', 'Robert Peel'], 'Wilberforce worked with campaigners such as Thomas Clarkson, Granville Sharp and Olaudah Equiano.', { accept: ['wilberforce'] }),
  fact('em.1807', 'empire', 'In which year did Britain abolish the slave TRADE?', '1807', ['1833', '1772', '1865'], 'The trade was banned in 1807; slavery itself in the British Empire was abolished by the 1833 Act.', {}),
  fact('em.1833', 'empire', 'Which act abolished slavery itself in most of the British Empire?', 'the Slavery Abolition Act of 1833', ['the Slave Trade Act of 1807', 'the Factory Act of 1833', 'Magna Carta'], 'It came into force in 1834, but forced “apprenticeships” lasted until 1838.', C),
  mcq('em.compensation', 'empire', 'Who received compensation when slavery was abolished in 1833?', [['Slave owners, who were paid £20 million', true], ['The people who had been enslaved', false, 'They received nothing.'], ['No one', false, 'Owners were compensated; enslaved people were not.']], '£20 million was about 40% of the government’s yearly budget. The loans took until 2015 to repay.'),
  mcq('em.resist', 'empire', 'Which shows enslaved people’s own role in ending slavery?', [['The Haitian Revolution (1791–1804) and the Jamaican rebellion led by Samuel Sharpe in 1831–32', true], ['Parliament acting entirely alone', false, 'Parliament acted, but resistance by enslaved people put real pressure on it.'], ['Nothing; enslaved people did not resist', false, 'Resistance was constant, from everyday refusal to large rebellions.']], 'Historians now stress that abolition was won by enslaved people as well as by British campaigners.'),
  mcq('em.india', 'empire', 'What happened after the Indian Rebellion of 1857?', [['The British government took direct control of India from the East India Company (the Raj)', true], ['India became independent', false, 'Independence came in 1947.'], ['India joined France', false, 'It came under direct British rule.']], 'In 1876 Queen Victoria was proclaimed Empress of India.'),
  fact('em.size', 'empire', 'By the early 1900s, about how much of the world’s land did the British Empire cover?', 'about a quarter', ['about a tenth', 'about half', 'almost all of it'], 'It was the largest empire in history, ruling over about 400 million people.', C),
  fact('em.india-indep', 'empire', 'In which year did India and Pakistan become independent?', '1947', ['1857', '1918', '1997'], 'Independence came after a long campaign led by figures such as Gandhi; partition caused terrible violence.', {}),
  // --- the vote
  fact('vt.1832', 'vote', 'Which 1832 Act gave the vote to more middle-class men and redrew constituencies?', 'the Great Reform Act', ['the Factory Act', 'the Representation of the People Act of 1918', 'the Bill of Rights'], 'Still only about 1 in 5 adult men could vote afterwards.', C),
  mcq('vt.chartists', 'vote', 'What did the Chartists (1838–48) campaign for?', [['Votes for all men, secret ballots and other reforms to Parliament', true], ['Votes for women', false, 'The People’s Charter asked for votes for all men.'], ['An end to the monarchy', false, 'Their six points were about Parliament.']], 'All but one of their six points (annual elections) eventually became law.'),
  mcq('vt.groups', 'vote', 'What was the difference between the suffragists and the suffragettes?', [['Suffragists used peaceful campaigning; suffragettes used direct, sometimes violent, action', true], ['Suffragists wanted the vote, suffragettes did not', false, 'Both wanted votes for women.'], ['There was no difference', false, 'Their methods were very different.']], 'Millicent Fawcett led the suffragists (NUWSS); Emmeline Pankhurst the suffragettes (WSPU).'),
  fact('vt.fawcett', 'vote', 'Who led the peaceful suffragists of the NUWSS?', 'Millicent Fawcett', ['Emmeline Pankhurst', 'Emily Davison', 'Nancy Astor'], 'Her statue stands in Parliament Square, the first statue of a woman there.', { accept: ['fawcett', 'millicent garrett fawcett'] }),
  fact('vt.pankhurst', 'vote', 'Who founded the Women’s Social and Political Union (the suffragettes) in 1903?', 'Emmeline Pankhurst', ['Millicent Fawcett', 'Florence Nightingale', 'Mary Wollstonecraft'], 'Its motto was “Deeds not words”.', { accept: ['pankhurst'] }),
  mcq('vt.davison', 'vote', 'What happened to Emily Wilding Davison at the Epsom Derby in 1913?', [['She was hit by the king’s horse and died of her injuries', true], ['She won the race', false, 'She ran onto the course during the race.'], ['She was elected to Parliament', false, 'Women could not stand for Parliament until 1918.']], 'Historians still debate exactly what she intended.'),
  fact('vt.1918', 'vote', 'In 1918 which women gained the vote?', 'women over 30 who met a property qualification', ['all women over 18', 'all women over 21', 'no women'], 'The same Act gave the vote to all men over 21.', C),
  fact('vt.1928', 'vote', 'In which year did women get the vote on equal terms with men (at 21)?', '1928', ['1918', '1903', '1969'], 'The Equal Franchise Act of 1928.', {}),
  mcq('vt.why1918', 'vote', 'Why did some women get the vote in 1918?', [['Women’s war work changed attitudes, building on decades of campaigning', true], ['The suffragettes had won a war', false, 'There was no such war.'], ['Men stopped wanting to vote', false, 'Men’s votes were extended too.']], 'Historians debate the weight of each factor: campaigning, war work and political change.'),
  fact('vt.astor', 'vote', 'Who was the first woman to take her seat as an MP, in 1919?', 'Nancy Astor', ['Constance Markievicz', 'Emmeline Pankhurst', 'Margaret Thatcher'], 'Constance Markievicz was elected first, in 1918, but as an Irish republican did not take her seat.', { accept: ['astor', 'lady astor'] }),
  // --- First World War
  fact('w1.spark', 'ww1', 'Whose assassination in Sarajevo on 28 June 1914 sparked the First World War?', 'Archduke Franz Ferdinand', ['Kaiser Wilhelm II', 'Tsar Nicholas II', 'King George V'], 'He was heir to the throne of Austria-Hungary; his killer was Gavrilo Princip.', { accept: ['franz ferdinand', 'archduke ferdinand'] }),
  mcq('w1.main', 'ww1', 'What do the letters MAIN stand for, as long-term causes of the war?', [['Militarism, Alliances, Imperialism, Nationalism', true], ['Money, Armies, Invasions, Navies', false, 'Close, but not quite.'], ['Monarchy, Assassination, Industry, Navy', false, 'The assassination was the short-term trigger.']], 'Long-term causes made war likely; the assassination was the spark.'),
  mcq('w1.belgium', 'ww1', 'Why did Britain declare war on 4 August 1914?', [['Germany invaded neutral Belgium, which Britain had promised to protect', true], ['Germany attacked London', false, 'That came later, with Zeppelin raids.'], ['Britain wanted German colonies', false, 'The treaty with Belgium was the official reason.']], 'The 1839 Treaty of London guaranteed Belgian neutrality.'),
  fact('w1.front', 'ww1', 'What was the line of trenches from the Channel coast to Switzerland called?', 'the Western Front', ['the Eastern Front', 'the Maginot Line', 'the Iron Curtain'], 'For most of the war it moved only a few miles either way.', C),
  mcq('w1.somme', 'ww1', 'What happened on 1 July 1916, the first day of the Battle of the Somme?', [['The British Army suffered about 57,000 casualties, its worst day ever', true], ['The war ended', false, 'The battle lasted until November 1916.'], ['Tanks won the battle in one day', false, 'Tanks were first used later in the battle, in September.']], 'Nearly 20,000 British soldiers were killed that day. The battle became a symbol of the war’s cost.'),
  fact('w1.tank', 'ww1', 'Which new weapon did the British first use at the Somme in September 1916?', 'the tank', ['the machine gun', 'the aeroplane', 'poison gas'], 'Early tanks were slow and unreliable, but pointed to the future.', { accept: ['tanks', 'tank'] }),
  mcq('w1.home', 'ww1', 'How did the war change life for women in Britain?', [['Many took jobs in factories, transport and farming, including dangerous work making shells', true], ['Women were forbidden to work', false, 'The opposite: their work was essential.'], ['Nothing changed for women', false, 'Over a million more women went out to work.']], 'Women making munitions were nicknamed “munitionettes”.'),
  fact('w1.conscription', 'ww1', 'In which year did Britain introduce conscription, forcing men to join the army?', '1916', ['1914', '1918', '1939'], 'Until then the army relied on volunteers. Conscientious objectors refused to fight on moral grounds.', {}),
  fact('w1.armistice', 'ww1', 'At what time and date did the fighting stop in 1918?', '11 a.m. on 11 November', ['midnight on 1 January', 'noon on 4 August', '11 a.m. on 6 June'], 'The eleventh hour of the eleventh day of the eleventh month: why we fall silent at 11 o’clock on Armistice Day.', C),
  fact('w1.owen', 'ww1', 'Which soldier-poet wrote “Dulce et Decorum Est”, about a gas attack?', 'Wilfred Owen', ['Rupert Brooke', 'Siegfried Sassoon', 'John McCrae'], 'Owen was killed a week before the Armistice. The title is Latin from Horace: “it is sweet and fitting (to die for your country)”.', { accept: ['owen'] }),
  mcq('w1.versailles', 'ww1', 'What did the Treaty of Versailles (1919) make Germany do?', [['Accept blame for the war, pay reparations, lose land and limit its army', true], ['Join the Allies', false, 'Germany was treated as the defeated enemy.'], ['Nothing; it was a fair peace', false, 'Many Germans called it a “Diktat”: a dictated peace.']], 'Resentment at the treaty later helped Hitler win support: a link between the two wars.'),
  // --- Second World War and the Holocaust
  fact('w2.start', 'ww2', 'Germany’s invasion of which country on 1 September 1939 led Britain to declare war?', 'Poland', ['Belgium', 'France', 'Czechoslovakia'], 'Britain and France declared war on 3 September 1939.', {}),
  fact('w2.churchill', 'ww2', 'Who became Prime Minister in May 1940?', 'Winston Churchill', ['Neville Chamberlain', 'Clement Attlee', 'David Lloyd George'], 'Churchill replaced Chamberlain as France was being invaded.', { accept: ['churchill'] }),
  order('w2.order', 'ww2', 'Put these events of the Second World War in order.', ['Evacuation from Dunkirk', 'Battle of Britain', 'Attack on Pearl Harbor', 'D-Day landings', 'VE Day'], ['1940', '1940', '1941', '1944', '1945'], 'Dunkirk (May–June 1940), the Battle of Britain (summer 1940), Pearl Harbor (December 1941), D-Day (June 1944), VE Day (8 May 1945).'),
  mcq('w2.pearl', 'ww2', 'Why was the Japanese attack on Pearl Harbor in December 1941 a turning point?', [['It brought the United States into the war', true], ['It ended the war in Europe', false, 'The war in Europe went on until 1945.'], ['It was the first battle of the war', false, 'The war had begun in 1939.']], 'American industry and soldiers transformed the war.'),
  fact('w2.stalingrad', 'ww2', 'At which Soviet city was a German army destroyed in the winter of 1942–43?', 'Stalingrad', ['Moscow', 'Berlin', 'Warsaw'], 'Stalingrad was a turning point on the Eastern Front.', { accept: ['volgograd'] }),
  fact('w2.holocaust', 'ww2', 'About how many Jewish people were murdered in the Holocaust?', 'about six million', ['about six thousand', 'about sixty thousand', 'about sixty million'], 'Around two thirds of Europe’s Jews. The Nazis also murdered Roma and Sinti people, disabled people and others.', C),
  order('w2.steps', 'ww2', 'Nazi persecution grew step by step. Put these in order.', ['Boycott of Jewish shops and businesses', 'Nuremberg Laws take away citizenship', 'Kristallnacht attacks', 'Wannsee Conference plans mass murder'], ['1933', '1935', '1938', '1942'], 'Understanding how persecution escalated in stages helps explain how the Holocaust could happen.'),
  mcq('w2.kristallnacht', 'ww2', 'What was Kristallnacht (9–10 November 1938)?', [['A night of violence across Germany when synagogues, Jewish homes and shops were attacked', true], ['A German victory in battle', false, 'It was violence against Jewish people inside Germany.'], ['A festival', false, 'The name means “night of broken glass”.']], 'Around 30,000 Jewish men were sent to concentration camps afterwards.'),
  fact('w2.kinder', 'ww2', 'What was the name of the rescue effort that brought about 10,000 mainly Jewish children to Britain in 1938–39?', 'the Kindertransport', ['Operation Dynamo', 'the Blitz', 'Operation Overlord'], 'Most of the children never saw their parents again.', C),
  fact('w2.memorial', 'ww2', 'Holocaust Memorial Day is 27 January. What happened on that day in 1945?', 'Soviet soldiers liberated Auschwitz-Birkenau', ['the war ended', 'Hitler came to power', 'D-Day began'], 'Auschwitz was the largest Nazi death camp; about 1.1 million people were murdered there.', C),
  fact('w2.anne', 'ww2', 'Which Jewish girl’s diary, written while hiding in Amsterdam, is read all over the world?', 'Anne Frank', ['Eva Schloss', 'Etty Hillesum', 'Hannah Senesh'], 'Anne was betrayed in 1944 and died in Bergen-Belsen in early 1945, aged 15.', { accept: ['frank'] }),
  fact('w2.ve', 'ww2', 'On which date was VE (Victory in Europe) Day?', '8 May 1945', ['11 November 1918', '6 June 1944', '15 August 1945'], 'The war against Japan ended in August 1945, after the atomic bombs on Hiroshima and Nagasaki.', C),
  // --- historical skills
  fact('sk.century', 'skills', 'Which century was the year 1066 in?', 'the 11th century', ['the 10th century', 'the 12th century', 'the 1st century'], 'The 11th century is the 1000s: add one to the first two digits.', { accept: ['11th', '11th century', 'eleventh century'] }),
  mcq('sk.bc', 'skills', 'Which is earlier: 490 BC or 323 BC?', [['490 BC', true], ['323 BC', false, 'BC dates count down towards year 1, so the bigger number is earlier.'], ['They are the same year', false, 'They are 167 years apart.']], 'BC years count backwards: 490 BC came 167 years before 323 BC.'),
  mcq('sk.primary', 'skills', 'Which is a PRIMARY source for the Battle of the Somme?', [['A letter written by a soldier who fought there', true], ['A history textbook written in 2015', false, 'That is secondary: written later, using other sources.'], ['A documentary made in 2006', false, 'That is secondary.']], 'Primary sources come from the time; secondary sources are later accounts and interpretations.'),
  mcq('sk.provenance', 'skills', 'When historians ask about a source’s provenance, what do they want to know?', [['Who made it, when, and why', true], ['How long it is', false, 'Length tells you little.'], ['Whether it has pictures', false, 'Provenance is about origin and purpose.']], 'Think NOP: Nature, Origin, Purpose.'),
  mcq('sk.biased', 'skills', 'A wartime poster exaggerates how happy factory workers were. Is it useless to a historian?', [['No: it is useful evidence of what the government wanted people to think', true], ['Yes: biased sources are useless', false, 'A biased source tells you a lot about its author’s purpose.'], ['Yes: posters are not real history', false, 'Propaganda is valuable evidence.']], 'Utility depends on the question you ask. Bias can itself be evidence.'),
  mcq('sk.cause', 'skills', 'What is the difference between a long-term cause and a trigger?', [['Long-term causes build up over years; a trigger is the event that finally sets things off', true], ['There is no difference', false, 'Good history essays separate them.'], ['A trigger is always the most important cause', false, 'Often the long-term causes matter more.']], 'Example: the alliance system (long-term) and Franz Ferdinand’s assassination (trigger).'),
  mcq('sk.significance', 'skills', 'Which question best tests whether an event was historically significant?', [['Did it cause big, lasting changes for many people?', true], ['Was it exciting?', false, 'Exciting events are not always significant.'], ['Did it happen a long time ago?', false, 'Age does not make something significant.']], 'Historians judge significance by depth, breadth and duration of impact, and by what it reveals.'),
  mcq('sk.continuity', 'skills', 'Which is an example of CONTINUITY between 1500 and 1800?', [['Most people still worked on the land', true], ['Steam engines replaced water wheels', false, 'That is a change.'], ['The Church of England was created', false, 'That is a change.']], 'Continuity means things that stayed the same while other things changed.'),
  mcq('sk.anachronism', 'skills', 'A film shows a Tudor knight checking a wristwatch. What is this mistake called?', [['An anachronism', true], ['An interpretation', false, 'An anachronism is something placed in the wrong time.'], ['A primary source', false, 'It is an error of timing.']], 'Wristwatches became common only in the 20th century.'),
  mcq('sk.consequence', 'skills', 'Which is a CONSEQUENCE of the Black Death, rather than a cause of it?', [['Peasants demanding higher wages', true], ['Fleas carried by rats', false, 'That helped cause the plague.'], ['Trade ships arriving from Europe', false, 'That helped spread it.']], 'Causes come before an event; consequences come after it.'),
  // --- stretch: sources and interpretations
  weighted('src.useful', 'sources', 'A 1915 British recruitment poster shows smiling soldiers. How useful is it for studying the First World War?', [['Useful for showing how the government tried to persuade men to join up, but not for what life at the front was really like, because its purpose was persuasion', 1, 'This uses content AND provenance, and links usefulness to a specific enquiry.'], ['Not useful, because it is biased', 0, 'Biased sources are useful for studying attitudes and propaganda.'], ['Very useful, because it shows soldiers were happy', 0.5, 'It shows what the government wanted people to believe, not necessarily the truth.']], 'GCSE answers judge utility by both content and provenance, for a particular question.'),
  weighted('src.differ', 'sources', 'Why might two historians give different interpretations of Oliver Cromwell?', [['They may use different sources, ask different questions, and write at different times with different concerns', 1, 'This explains how interpretations are made.'], ['One of them must be lying', 0, 'Disagreement usually comes from evidence and focus, not lies.'], ['Because history is just opinion', 0.25, 'Interpretations must be supported by evidence; some are better supported than others.']], 'Interpretations are shaped by evidence, emphasis and context.'),
  mcq('src.date', 'sources', 'An account of the Black Death was written in 1349 by a monk. Which point about its provenance is strongest?', [['Written during the plague, so it shows contemporary fear and belief, though a monk might stress God’s punishment', true], ['It was written by a monk, so it is all lies', false, 'Monks were key record-keepers; their viewpoint needs weighing, not dismissing.'], ['It was written long after the event', false, '1349 is during the plague.']], 'Weigh what the author’s position and timing add and what they might distort.'),
  mcq('src.cross', 'sources', 'How can a historian check whether a source is reliable?', [['Cross-reference it with other sources and with what is already known', true], ['Check if it is printed in a book', false, 'Printing does not make something true.'], ['Count how many words it has', false, 'Length tells you little.']], 'Corroboration is one of the historian’s main tools.'),
  weighted('src.essay', 'sources', '“The suffragettes were the main reason women got the vote in 1918.” Which plan would earn the highest marks?', [['Weigh the suffragettes against other factors (suffragists, war work, political change), then reach a supported judgement', 1, 'This evaluates several factors and judges the relative importance.'], ['Describe everything the suffragettes did', 0.25, 'Description without judgement scores low.'], ['Agree completely and give one example', 0, 'One-sided answers miss the other factors.']], 'GCSE essays reward balance, evidence and a clear, justified conclusion.'),
  mcq('src.cartoon', 'sources', 'What should you do FIRST when analysing a political cartoon?', [['Work out its date, origin and the message the cartoonist wanted to give', true], ['Decide whether it is funny', false, 'Humour is a technique; the message matters.'], ['Count the people in it', false, 'Focus on the message and context.']], 'Context and purpose unlock what a cartoon is saying.'),
  // --- stretch: the Cold War
  mcq('cw2.what', 'cold-war', 'Why was the Cold War called “cold”?', [['The USA and USSR never fought each other directly, though they competed in other ways', true], ['It was fought in Antarctica', false, 'It was a global rivalry.'], ['It happened only in winter', false, 'It lasted from about 1945 to 1991.']], 'They fought through arms races, spying, propaganda and wars between their allies.'),
  mcq('cw2.ideas', 'cold-war', 'Which pair of ideologies divided the two superpowers?', [['Capitalism and democracy (USA) against communism (USSR)', true], ['Catholic and Protestant', false, 'It was about economic and political systems.'], ['Monarchy and republic', false, 'Both were republics.']], 'Each side believed its system was best and feared the other’s spread.'),
  fact('cw2.curtain', 'cold-war', 'Who said in 1946 that an “iron curtain” had descended across Europe?', 'Winston Churchill', ['Joseph Stalin', 'John F. Kennedy', 'Harry Truman'], 'He spoke at Fulton, Missouri.', { accept: ['churchill'] }),
  mcq('cw2.airlift', 'cold-war', 'What was the Berlin Airlift (1948–49)?', [['Western planes flew in food and fuel to West Berlin after the Soviets blocked roads and railways', true], ['An air battle over Berlin', false, 'No shots were fired.'], ['The building of the Berlin Wall', false, 'That was in 1961.']], 'Planes landed every few minutes for almost a year.'),
  fact('cw2.wall', 'cold-war', 'In which year did the Berlin Wall fall?', '1989', ['1961', '1991', '1945'], 'It was built in 1961 and opened on 9 November 1989.', {}),
  mcq('cw2.cuba', 'cold-war', 'Why was the Cuban Missile Crisis (October 1962) so dangerous?', [['The USSR had placed nuclear missiles in Cuba, close to the USA, and both sides came close to nuclear war', true], ['Cuba invaded the USA', false, 'Cuba did not invade.'], ['The Berlin Wall fell', false, 'That was 1989.']], 'Kennedy and Khrushchev found a deal after thirteen tense days.'),
  fact('cw2.sputnik', 'cold-war', 'Which country launched Sputnik, the first artificial satellite, in 1957?', 'the USSR', ['the USA', 'Britain', 'China'], 'Sputnik started the Space Race; the USA landed the first people on the Moon in 1969.', { accept: ['ussr', 'soviet union', 'russia'] }),
  fact('cw2.end', 'cold-war', 'In which year did the Soviet Union break up, ending the Cold War?', '1991', ['1989', '1962', '2000'], 'It split into 15 independent countries in December 1991.', {}),
  // --- stretch: the Islamic Golden Age
  fact('ga.baghdad', 'golden-age', 'Which city, founded in 762 as the capital of the Abbasid caliphs, became a world centre of learning?', 'Baghdad', ['Rome', 'Paris', 'Cairo'], 'At its height it may have been the largest city in the world.', {}),
  fact('ga.house', 'golden-age', 'What was the famous library and centre of translation in Baghdad called?', 'the House of Wisdom', ['the Library of Alexandria', 'the Parthenon', 'the Academy'], 'Scholars there translated Greek works by Aristotle, Euclid and Galen into Arabic.', C),
  fact('ga.khwarizmi', 'golden-age', 'Which scholar’s book gave us the word “algebra”, and whose name gave us “algorithm”?', 'al-Khwarizmi', ['Ibn Sina', 'Ibn al-Haytham', 'Euclid'], 'His book on al-jabr (restoring) laid foundations of algebra.', { accept: ['al khwarizmi', 'khwarizmi', 'al-khwarizmi'] }),
  fact('ga.ibnsina', 'golden-age', 'Which Persian doctor wrote “The Canon of Medicine”, used in European universities for 500 years?', 'Ibn Sina (Avicenna)', ['al-Khwarizmi', 'Galen', 'Hippocrates'], 'Ibn Sina built on Greek medicine and added his own observations.', { accept: ['ibn sina', 'avicenna'] }),
  mcq('ga.greek', 'golden-age', 'How did many Ancient Greek books survive to reach medieval Europe?', [['They were translated into Arabic in the Islamic world, then into Latin', true], ['They were kept in Viking libraries', false, 'Arabic translations were the key route.'], ['They were buried in Athens until 1900', false, 'Many reached Europe through Spain and Sicily in the 1100s.']], 'Toledo in Spain was a great centre where Arabic texts were translated into Latin.'),
  mcq('ga.numbers', 'golden-age', 'Where did our “Arabic” numerals, including zero, originally come from?', [['India, and they spread to Europe through the Arab world', true], ['Ancient Rome', false, 'Romans used letters: I, V, X.'], ['Ancient Egypt', false, 'Egyptian numerals were different symbols.']], 'They are sometimes called Hindu–Arabic numerals.'),
  fact('ga.haytham', 'golden-age', 'Which scholar of Cairo wrote the “Book of Optics”, showing that we see because light enters the eye?', 'Ibn al-Haytham', ['Ibn Sina', 'al-Khwarizmi', 'Aristotle'], 'He tested ideas with experiments, an early step towards the scientific method.', { accept: ['al-haytham', 'alhazen', 'ibn al haytham'] }),
  fact('ga.end', 'golden-age', 'Which invaders sacked Baghdad in 1258, destroying the House of Wisdom?', 'the Mongols', ['the Vikings', 'the Romans', 'the Normans'], 'Chroniclers said the River Tigris ran black with ink from the books thrown into it.', { accept: ['mongols'] }),
];

